mapper.select:
SELECT t1.CORP_GR AS corpGr , t1.FUND_CD AS fundCd , ia.FUND_NM AS fundNm , TO_CHAR(t1.TR_YMD, 'YYYY-MM-DD') AS trYmd , t1.IN_AEK AS inAek , t1.OUT_AEK AS outAek , t1.IO_JO AS ioJo , t1.WONBON_AEK AS wonbonAek , CASE WHEN t1.TR_YMD >= F_WORKDATE(t1.CORP_GR) THEN 1 ELSE 0 END AS pVisible FROM SZT0IO t1 , SZM0IA ia WHERE t1.CORP_GR = #{corpGr}
AND TRUNC(t1.TR_YMD) = TO_DATE(REPLACE(#{trYmd}, '-', ''), 'YYYYMMDD')
AND ia.CORP_GR = t1.CORP_GR AND ia.FUND_CD = t1.FUND_CD ORDER BY t1.FUND_CD ASC
